static boolean isSelectOnly(String sql) {
    try {
        Statements statements = CCJSqlParserUtil.parseStatements(sql);
        return statements.size() == 1 && statements.get(0) instanceof PlainSelect;
    } catch (JSQLParserException e) {
        return false;
    }
}

record RefundArgs(
    @NotNull @Pattern(regexp = "ORD-\\d{6}") String orderId,
    @NotNull @DecimalMin(value = "0", inclusive = false) @DecimalMax("500") BigDecimal amount) {}

Answer generateValid(String prompt, int maxAttempts) {
    String hint = "";
    for (int attempt = 0; attempt < maxAttempts; attempt++) {
        String text = llm.apply(prompt + hint);
        try {
            return mapper.readValue(text, Answer.class);
        } catch (JsonProcessingException e) {
            hint = "\nPrevious output was invalid: " + e.getMessage();
        }
    }
    throw new IllegalStateException("no valid output");
}

PaymentResult processPayment(String key, long amount) {
    return RESULTS.computeIfAbsent(key, k -> charge(amount));
}

Object callTool(String name, Map<String, Object> args) {
    if (!ALLOWED.contains(name)) {
        throw new SecurityException("tool not allowed: " + name);
    }
    return TOOLS.get(name).apply(args);
}
